const html = $json.data;

if (!html) {
  return [{
    json: {
      success: false,
      error: "NO_HTML"
    }
  }];
}

// Extract only the section we need.
const startMarker = "<h2>Waarvoor krijgt u een tegemoetkoming?</h2>";
const endMarker = "<h2>Onder welke voorwaarden hebt u recht op een tegemoetkoming?</h2>";

const start = html.indexOf(startMarker);
const end = html.indexOf(endMarker);

if (start === -1 || end === -1 || end <= start) {
  return [{
    json: {
      success: false,
      error: "CRITERIA_SECTION_NOT_FOUND"
    }
  }];
}

const sectionHtml = html.slice(start, end);

// Convert HTML to readable text.
const text = sectionHtml
  .replace(/<br\s*\/?>/gi, "\n")
  .replace(/<\/li>/gi, "\n")
  .replace(/<\/p>/gi, "\n")
  .replace(/<[^>]+>/g, "")
  .replace(/&nbsp;/gi, " ")
  .replace(/&lt;/gi, "<")
  .replace(/&gt;/gi, ">")
  .replace(/&ge;/gi, ">=")
  .replace(/&le;/gi, "<=")
  .replace(/&amp;/gi, "&")
  .replace(/&#039;/gi, "'")
  .replace(/&eacute;/gi, "é")
  .replace(/&egrave;/gi, "è")
  .replace(/&agrave;/gi, "à")
  .replace(/\r/g, "")
  .replace(/[ \t]+/g, " ")
  .replace(/\n\s*\n+/g, "\n")
  .trim();

return [{
  json: {
    success: true,
    source: "RIZIV",
    sourceUrl: "https://www.riziv.fgov.be/nl/thema-s/verzorging-kosten-en-terugbetaling/wat-het-ziekenfonds-terugbetaalt/medische-hulpmiddelen-medisch-materiaal/implantaten-en-medische-hulpmiddelen/vergoeding-van-cochleaire-implantaten",
    section: "Waarvoor krijgt u een tegemoetkoming?",
    extractedAt: new Date().toISOString(),
    criteriaText: text
  }
}];

const d = $input.first().json;

if (!d.success || !d.criteriaText) {
  return [{
    json: {
      success: false,
      error: "NO_RIZIV_CRITERIA_TEXT",
      message: "No extracted RIZIV criteria were found."
    }
  }];
}

return [{
  json: {
    success: true,

    country: "BE",
    authority: "RIZIV",
    criteriaName: "Cochlear implant reimbursement criteria",

    sourceUrl: d.sourceUrl || null,
    checkedAt: d.extractedAt || new Date().toISOString(),

    rules: {
      bilateralSevere: {
        minPtaEachEar: 70,

        under18: {
          implant: "bilateral"
        },

        age18Plus: {
          implant: "unilateral"
        },

        note: "If the period between first and second implantation is >= 4 years, additional criteria apply for the contralateral implant."
      },

      bilateralSevereWithOssificationOrAuditoryNeuropathy: {
        minPtaEachEar: 70,

        under18: {
          implant: "bilateral"
        },

        conditions: [
          "bilateral ossification",
          "auditory neuropathy"
        ]
      },

      asymmetricBilateral: {
        betterEar: {
          ptaGreaterThan: 30
        },

        worseEar: {
          under18MinPta: 85,
          age18PlusMinPta: 70
        },

        under18: {
          implant: "worstEar"
        },

        age18Plus: {
          implant: "worstEar",
          requiresTrialPeriods: true,
          trialPeriodEffectiveFrom: "2026-01-01"
        }
      },

      unilateralDeafness: {
        affectedEar: {
          under18MinPta: 85,
          age18PlusMinPta: 70
        },

        normalEar: {
          maxPta: 30
        },

        under4: {
          condition: "congenital"
        },

        under18: {
          condition: "acquired"
        },

        age18Plus: {
          condition: "acquired",
          requiresTrialPeriods: true,
          trialPeriodEffectiveFrom: "2026-01-01"
        },

        maxYearsBetweenDiagnosisAndImplantation: 7
      }
    },

    reimbursement: {
      firstImplant: true,
      externalSoundProcessor: true,
      replacementImplant: true,
      replacementSoundProcessor: true
    },

    rawCriteriaText: d.criteriaText
  }
}];
